SELECT
 (SELECT count(*)=4 AND bool_and(c.relrowsecurity) FROM pg_class c WHERE c.oid IN(to_regclass('petro_private.service_refund_decisions'),to_regclass('petro_private.service_refund_allocations'),to_regclass('petro_private.service_refund_documents'),to_regclass('petro_private.service_receivable_settlements')))
 AND NOT EXISTS(SELECT 1 FROM pg_class c CROSS JOIN(VALUES('anon'),('authenticated'),('service_role'))r(name) WHERE c.oid IN(to_regclass('petro_private.service_refund_decisions'),to_regclass('petro_private.service_refund_allocations'),to_regclass('petro_private.service_refund_documents'),to_regclass('petro_private.service_receivable_settlements')) AND has_table_privilege(r.name,c.oid,'SELECT,INSERT,UPDATE,DELETE'))
 AND(SELECT count(*)=1 AND bool_and(p.prosecdef AND p.proconfig=ARRAY['search_path=""']::text[] AND has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('service_role',p.oid,'EXECUTE')) FROM pg_proc p WHERE p.oid=to_regprocedure('public.petro_decide_service_refund(uuid,bigint,text,text,text,text)'))
 AND(SELECT count(*)=1 AND bool_and(NOT p.prosecdef AND p.proconfig=ARRAY['search_path=""']::text[] AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('service_role',p.oid,'EXECUTE')) FROM pg_proc p WHERE p.oid=to_regprocedure('petro_private.validate_service_receivable_settlement()'))
 AND(SELECT count(*)=5 FROM pg_trigger WHERE NOT tgisinternal AND tgenabled='O' AND tgname IN('service_refund_decision_immutable','service_refund_allocation_immutable','service_refund_document_immutable','service_receivable_settlement_immutable','service_receivable_settlement_validate'))
 AND coalesce((SELECT NOT has_sequence_privilege('anon',c.oid,'USAGE,SELECT,UPDATE') AND NOT has_sequence_privilege('authenticated',c.oid,'USAGE,SELECT,UPDATE') AND NOT has_sequence_privilege('service_role',c.oid,'USAGE,SELECT,UPDATE') FROM pg_class c WHERE c.oid=to_regclass('petro_private.service_credit_document_seq')),false)
 AND EXISTS(SELECT 1 FROM public.petro_finance_accounts WHERE account_kind='merchant_refund_receivable' AND normal_side='debit' AND account_code='SYS-MERCHANT-REFUND-RECEIVABLE')
 AS present;
